def parse_duration(duration: str) -> int:
    """Parse a duration string and return its length in milliseconds.

    Durations can be specified as a number of milliseconds, or with optional
    hour, minute, and second components (for example, ``1h 2m 3s``).
    """
    duration = duration.strip()
    if not duration:
        raise ValueError("Duration must not be empty")

    if re.fullmatch(r'[0-9]+', duration):
        return int(duration)

    duration_re = re.compile(
        r'(?:(?P<hours>[0-9]+(?:\.[0-9]+)?)h\s*)?'
        r'(?:(?P<minutes>[0-9]+(?:\.[0-9]+)?)m\s*)?'
        r'(?:(?P<seconds>[0-9]+(?:\.[0-9]+)?)s)?')
    match = duration_re.fullmatch(duration)
    if match is None or not any(match.groupdict().values()):
        raise ValueError("Invalid duration: {!r}".format(duration))

    milliseconds = fractions.Fraction()
    for unit, multiplier in [('hours', 60 * 60 * 1000),
                             ('minutes', 60 * 1000),
                             ('seconds', 1000)]:
        value = match.group(unit)
        if value is not None:
            milliseconds += fractions.Fraction(value) * multiplier
    return int(milliseconds)


def format_seconds(total_seconds: int) -> str:
    """Format a count of seconds to get a [H:]M:SS string."""
    prefix = '-' if total_seconds < 0 else ''
    hours, rem = divmod(abs(round(total_seconds)), 3600)
    minutes, seconds = divmod(rem, 60)
    chunks = []
    if hours:
        chunks.append(str(hours))
        min_format = '{:02}'
    else:
        min_format = '{}'
    chunks.append(min_format.format(minutes))
    chunks.append('{:02}'.format(seconds))
    return prefix + ':'.join(chunks)


def format_size(size: Optional[float], base: int = 1024, suffix: str = '') -> str:
    """Format a byte size so it's human readable.

    Inspired by http://stackoverflow.com/q/1094841
    """
    prefixes = ['', 'k', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y']
    if size is None:
        return '?.??' + suffix
    for p in prefixes:
        if -base < size < base:
            return '{:.02f}{}{}'.format(size, p, suffix)
        size /= base
    return '{:.02f}{}{}'.format(size, prefixes[-1], suffix)


